import { expect, test } from "@playwright/test";
import path from "node:path";

// Synthetic fixtures generated by backend/scripts/make_sample_documents.py (no real patient data).
const SAMPLES = path.resolve(__dirname, "../../evaluation/datasets/synthetic");
const DISCLAIMER = /does not diagnose conditions/;

// The first-visit welcome pop-up covers the page; most tests start as a returning visitor (test 9 checks the pop-up).
test.beforeEach(async ({ page }, info) => {
  if (!info.title.startsWith("9.")) await page.addInitScript(() => localStorage.setItem("fitscan.welcomeSeen", "1"));
});

async function signUp(page: import("@playwright/test").Page) {
  await page.getByLabel("Email").fill(`e2e-${Date.now()}-${Math.round(Math.random() * 1e6)}@fitscan-demo.org`);
  await page.getByLabel("Password", { exact: true }).fill("e2e-password-1");
  await page.getByLabel("Confirm password").fill("e2e-password-1");
  await page.getByRole("checkbox").check();
  await page.getByRole("button", { name: "Create account" }).click();
}

test("1. every page carries the disclaimer (BR-13)", async ({ page }) => {
  for (const route of ["/dashboard", "/analysis", "/tests", "/history", "/profile", "/privacy", "/terms"]) {
    await page.goto(route);
    await expect(page.getByText(DISCLAIMER).first()).toBeVisible();
    const legal = page.getByRole("navigation", { name: "Legal" });
    await expect(legal.getByRole("link", { name: "Privacy Policy" })).toBeVisible();
    await expect(legal.getByRole("link", { name: "Terms & Conditions" })).toBeVisible();
  }
  await page.getByRole("navigation", { name: "Legal" }).getByRole("link", { name: "Privacy Policy" }).click();
  await expect(page.getByRole("heading", { name: "Privacy Policy", level: 1 })).toBeVisible();
  await expect(page.getByText("Grievance Officer and contact").first()).toBeVisible();
  await page.getByRole("navigation", { name: "Legal" }).getByRole("link", { name: "Terms & Conditions" }).click();
  await expect(page.getByRole("heading", { name: "Terms & Conditions", level: 1 })).toBeVisible();
});

test("2. upload lab report -> verify -> AI analysis with labelled sources (BR-10)", async ({ page }) => {
  await page.goto("/analysis");
  await page.getByLabel("Choose file").setInputFiles(path.join(SAMPLES, "apex_cbc.pdf"));
  await page.getByRole("button", { name: "Upload & process" }).click();
  await expect(page.getByText("3. Check the extracted values")).toBeVisible();
  await expect(page.getByText("Hemoglobin").first()).toBeVisible();
  await page.getByRole("button", { name: "Confirm all values" }).click();
  await expect(page.getByText("Values confirmed")).toBeVisible();
  await page.getByRole("button", { name: "Check AI Medical Report Analysis" }).click();
  await expect(page.getByText("AI Medical Report Analysis")).toBeVisible();
  await expect(page.getByText("AI-generated").first()).toBeVisible();
  await expect(page.getByText("Extracted").first()).toBeVisible();
  await expect(page.getByRole("link", { name: "Download PDF summary" })).toBeVisible();
});

test("3. analysis preview locked until a report is attached; Tests & Centres is log-in-to-unlock", async ({ page }) => {
  await page.goto("/analysis");
  await expect(page.getByText("Doctor's prescription")).toHaveCount(0);
  await expect(page.getByText("Upload a lab report to unlock your analysis.")).toBeVisible();
  await page.getByLabel("Choose file").setInputFiles(path.join(SAMPLES, "apex_cbc.pdf"));
  await expect(page.getByText(/Next: press Upload & process/)).toBeVisible();
  await page.getByRole("button", { name: "Upload & process" }).click();
  await page.getByRole("button", { name: "Confirm all values" }).click();
  await page.getByRole("link", { name: "Go to Tests & Centres" }).click();
  await expect(page.getByText("Log in to unlock Tests & Centres")).toBeVisible();   // guest
  await page.getByRole("link", { name: "Create free account" }).click();
  await signUp(page);
  await page.waitForURL("**/tests?doc=*");                                           // back where they were
  await expect(page.getByText("Which test do you need?")).toBeVisible();
  await expect(page.getByRole("button", { name: "Complete Blood Count", pressed: true })).toBeVisible();
  // Optional type of doctor - nothing chosen by default; picking one adds it to the search.
  const doctor = page.getByLabel("Type of doctor (optional)");
  await expect(doctor).toHaveValue("");
  await doctor.selectOption("CARDIOLOGIST");
  await expect(page.getByRole("button", { name: "Find centres for 1 test(s) + Cardiologist (heart)" })).toBeVisible();
  if (process.env.SHOT_DIR) await page.screenshot({ path: path.join(process.env.SHOT_DIR, "tests-doctor.png") });
});

test("6. floating assistant on every page (log in to unlock) + dashboard charts", async ({ page }) => {
  await page.goto("/dashboard");
  await expect(page.getByText("Results by body system")).toBeVisible();
  await expect(page.getByText("Recent activity")).toHaveCount(0);
  await page.getByRole("button", { name: "Talk to the FITSCAN assistant" }).click();
  await expect(page.getByText("Log in to unlock the assistant")).toBeVisible();     // guest
  await page.goto("/register");
  await signUp(page);
  await page.waitForURL("**/dashboard");
  for (const route of ["/tests", "/history", "/dashboard"]) {
    await page.goto(route);
    await expect(page.getByRole("button", { name: "Talk to the FITSCAN assistant" })).toBeVisible();
  }
  await page.getByRole("button", { name: "Talk to the FITSCAN assistant" }).click();
  await page.getByLabel("Message the assistant").fill("How do I compare my reports?");
  await page.getByRole("button", { name: "Send" }).click();
  await expect(page.getByText(/tick two or more lab reports/)).toBeVisible();
  await expect(page.getByRole("link", { name: /Compare reports/ }).last()).toBeVisible();
});

test("4. register keeps guest documents and history lists them", async ({ page }) => {
  await page.goto("/analysis");
  await page.getByLabel("Choose file").setInputFiles(path.join(SAMPLES, "citycare_lipid_noheader.pdf"));
  await page.getByRole("button", { name: "Upload & process" }).click();
  await expect(page.getByText("3. Check the extracted values")).toBeVisible();
  await page.goto("/register");
  await signUp(page);
  await page.waitForURL("**/dashboard");
  await page.goto("/history");
  await expect(page.getByText("citycare_lipid_noheader.pdf")).toBeVisible();
});

test("7. scanned report: auto-check & confirm without manual clean-up", async ({ page }) => {
  await page.goto("/analysis");
  await page.getByLabel("Choose file").setInputFiles(path.join(SAMPLES, "apex_cbc_scan.png"));
  await page.getByRole("button", { name: "Upload & process" }).click();
  await expect(page.getByText("3. Check the extracted values")).toBeVisible({ timeout: 90_000 });
  await expect(page.getByRole("button", { name: "Save changes" })).toHaveCount(0);
  const auto = page.getByRole("button", { name: "Auto-check & confirm" }).last();
  if (await auto.isVisible()) {
    await auto.click();
    const dialog = page.getByRole("dialog");
    const date = dialog.getByLabel("Report date (printed on report)");
    if (await date.isVisible()) await date.fill("2024-02-04");
    await dialog.getByRole("button", { name: "Auto-check & confirm" }).click();
  } else {
    await page.getByRole("button", { name: "Confirm all values" }).click();
  }
  await expect(page.getByText("Values confirmed")).toBeVisible();
  await expect(page.getByRole("button", { name: "Check AI Medical Report Analysis" })).toBeEnabled();
});

test("8. health score + BMI: locked for guests, unlocked after sign-up; BMI also set in Profile", async ({ page }) => {
  await page.goto("/dashboard");
  await expect(page.getByText("Log in to unlock your lab health score")).toBeVisible();
  await expect(page.getByText("Log in to unlock BMI")).toBeVisible();
  await page.goto("/analysis");
  await page.getByLabel("Choose file").setInputFiles(path.join(SAMPLES, "apex_cbc.pdf"));
  await page.getByRole("button", { name: "Upload & process" }).click();
  await page.getByRole("button", { name: "Confirm all values" }).click();
  await expect(page.getByText("Values confirmed")).toBeVisible();
  await page.goto("/register?next=/dashboard");
  await signUp(page);
  await page.waitForURL("**/dashboard");
  await expect(page.getByLabel(/^Score \d+(\.\d)? out of 10$/)).toBeVisible();     // the guest report moved into the account
  await page.getByLabel("Height (cm)").fill("170");
  await page.getByLabel("Weight (kg)").fill("65");
  await page.getByRole("button", { name: "Calculate BMI" }).click();
  await expect(page.getByText("22.5")).toBeVisible();
  await expect(page.getByText("Healthy weight").first()).toBeVisible();
  await page.goto("/profile");                                                       // same values, optional, in Profile
  await expect(page.getByLabel("Height in cm (optional)")).toHaveValue("170");
  await page.getByLabel("Weight in kg (optional)").fill("80");
  await expect(page.getByText(/Your BMI: 27\.7/)).toBeVisible();
  await page.getByRole("button", { name: "Save", exact: true }).first().click();
  await page.goto("/dashboard");
  await expect(page.getByText("27.7")).toBeVisible();
  await page.getByRole("button", { name: "Remove BMI" }).click();
  await expect(page.getByLabel("Height (cm)")).toBeVisible();
});

test("9. first visit shows the upload pop-up; guests get a log-in reminder after their analysis", async ({ page }) => {
  await page.goto("/dashboard");
  const welcome = page.getByRole("dialog", { name: "Welcome to FITSCAN" });
  await expect(welcome.getByText("Upload your blood test report")).toBeVisible();
  await welcome.getByRole("link", { name: "Upload my blood report" }).click();
  await page.waitForURL("**/analysis");
  await page.goto("/dashboard");
  await expect(page.getByRole("dialog", { name: "Welcome to FITSCAN" })).toHaveCount(0);  // only once
  await page.goto("/analysis");
  await page.getByLabel("Choose file").setInputFiles(path.join(SAMPLES, "apex_cbc.pdf"));
  await page.getByRole("button", { name: "Upload & process" }).click();
  await page.getByRole("button", { name: "Confirm all values" }).click();
  await page.getByRole("button", { name: "Check AI Medical Report Analysis" }).click();
  const reminder = page.getByRole("dialog", { name: "Unlock more features" });
  await expect(reminder.getByText("Your analysis is ready!")).toBeVisible();
  await expect(reminder.getByText("Tests & Centres")).toBeVisible();
  await reminder.getByRole("button", { name: "Maybe later" }).click();
  await expect(reminder).toHaveCount(0);
});

test("5. invalid file type is rejected client-side (FR-UPL-2)", async ({ page }) => {
  await page.goto("/analysis");
  await page.getByLabel("Choose file").setInputFiles({ name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("hello") });
  await expect(page.getByText("Only PDF, JPG, JPEG and PNG files are supported.")).toBeVisible();
});
